import{_ as e,o as r,c as t,a5 as h}from"./chunks/framework.CnBNXlt7.js";const _=JSON.parse('{"title":"这又是什么呢","description":"","frontmatter":{},"headers":[],"relativePath":"thought/temp.md","filePath":"thought/temp.md","lastUpdated":1752144819000}'),o={name:"thought/temp.md"};function l(i,a,n,p,d,b){return r(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="这又是什么呢" tabindex="-1">这又是什么呢 <a class="header-anchor" href="#这又是什么呢" aria-label="Permalink to &quot;这又是什么呢&quot;">​</a></h1><p>原来社恐还能有这一层意思啊 —— 不认识/不熟，觉得很尴尬</p><p>最近悟出了什么道理？(<a href="https://www.zhihu.com/question/538335062/answer/2759257121" target="_blank" rel="noreferrer">原回答</a>)</p><ol><li>人最顶级的能力是屏蔽力，任何消耗你的人和事，多看一眼都是你的不对</li><li>不必过度为人提供情绪价值，可以理解别人的处境，边界感很重要，让别人开心不是你的责任。</li><li>人最重要的特质是专注，专注于某一件事。纯粹而利落，这就是千钧之力。你不必活成很多个样子，当你专注于某件事情时，可以解释很多事。</li></ol><h2 id="_2025-06-17" tabindex="-1">2025/06/17 <a class="header-anchor" href="#_2025-06-17" aria-label="Permalink to &quot;2025/06/17&quot;">​</a></h2><p>漫长的等待</p><p>你觉得可以赶上三分钟后到来的公交车，却偏偏赶不上<br> 然后你决定等下一趟，你看好了时间，下一趟在10分钟后。可偏偏他开了20分钟<br> 你觉得可以赶上的，他开的极快。你觉得可以等10分钟就来，他偏偏是开的最慢的</p><p>对于这种慢车，上了车也是觉得最慢的。吃满全部红绿灯，右转绿灯也不走&amp;……</p><h2 id="_2020" tabindex="-1">2020 <a class="header-anchor" href="#_2020" aria-label="Permalink to &quot;2020&quot;">​</a></h2><h3 id="_04-02-08-57" tabindex="-1">04/02 08:57 <a class="header-anchor" href="#_04-02-08-57" aria-label="Permalink to &quot;04/02 08:57&quot;">​</a></h3><p>梦中生活与现实生活大致相同。甚至在梦中遭遇的，物理上受到的影响会附加在当前现实中，比如干吼-嗓子干疼、跳崖-惊吓失魂…<br> 梦，何不为是时空旅行，每晚都是在与当前现实相似度最高的平时时空互相交换生活</p><h3 id="_03-27-12-42" tabindex="-1">03/27 12:42 <a class="header-anchor" href="#_03-27-12-42" aria-label="Permalink to &quot;03/27 12:42&quot;">​</a></h3><p>口腔溃疡是因为吃 来自外太空的青椒 受到太空辐射 然后人体不适应性</p><h3 id="_03-24-21-44" tabindex="-1">03/24 21:44 <a class="header-anchor" href="#_03-24-21-44" aria-label="Permalink to &quot;03/24 21:44&quot;">​</a></h3><p>收录<br> 低调不张狂 静坐常思己过 长期目标短期目标都不能少 那并不是你失去的，那是从未属于过你的 ​​​​ 但愿你的眼睛，只看得到笑容。</p><h3 id="_03-02-03-53" tabindex="-1">03/02 03：53 <a class="header-anchor" href="#_03-02-03-53" aria-label="Permalink to &quot;03/02 03：53&quot;">​</a></h3><p>总是被回忆戳痛</p><h3 id="_02-07-10-22" tabindex="-1">02/07 10:22 <a class="header-anchor" href="#_02-07-10-22" aria-label="Permalink to &quot;02/07 10:22&quot;">​</a></h3><p>警察只是按要求训诫， 主播只是按稿子播报， 后台只是按上面意思删帖撤热搜。</p><p>大家都认为自己是好人，一切是生活所迫。</p><p>只有当每一个人都敢说“我拒绝撒谎”，“我拒绝执行”的时候，我们才不会在某一天求助无门，走投无路，像狗一样地死去。</p><p>但你敢吗。你不敢。</p><p>所以请记得，无论这个世界最终烂成什么样子，都是在我们的默许之下完成的。</p><h2 id="_2019" tabindex="-1">2019 <a class="header-anchor" href="#_2019" aria-label="Permalink to &quot;2019&quot;">​</a></h2><h3 id="_12-15" tabindex="-1">12/15 <a class="header-anchor" href="#_12-15" aria-label="Permalink to &quot;12/15&quot;">​</a></h3><p>低调不张狂</p><p>可以画皮吗？给我画张皮</p><h3 id="_11-10" tabindex="-1">11/10 <a class="header-anchor" href="#_11-10" aria-label="Permalink to &quot;11/10&quot;">​</a></h3><p>当所有人都无脑玩梗的时候，那种感觉就不再是心有灵犀，而是平庸。</p><h3 id="_10-03" tabindex="-1">10/03 <a class="header-anchor" href="#_10-03" aria-label="Permalink to &quot;10/03&quot;">​</a></h3><p>楼下一个男人病得要死， 那间壁的一家唱着留声机； 对面是弄孩子。 楼上有两人狂笑； 还有打牌声。 河中的船上有女人哭着她死去的母亲。 人类的悲欢并不相通，我只觉得他们吵闹</p><h3 id="_07-23" tabindex="-1">07/23 <a class="header-anchor" href="#_07-23" aria-label="Permalink to &quot;07/23&quot;">​</a></h3><p>我人生的每一个时间段所持的 价值体系、思想观念都不一样 那么，我真的是多重现实的我吗</p><h3 id="_06-22" tabindex="-1">06/22 <a class="header-anchor" href="#_06-22" aria-label="Permalink to &quot;06/22&quot;">​</a></h3><p>睡饱了就起来 不要贪睡做一堆梦</p><h3 id="_06-20" tabindex="-1">06/20 <a class="header-anchor" href="#_06-20" aria-label="Permalink to &quot;06/20&quot;">​</a></h3><p>口腔溃疡 是否积累的效应</p><h3 id="_05-21" tabindex="-1">05/21 <a class="header-anchor" href="#_05-21" aria-label="Permalink to &quot;05/21&quot;">​</a></h3><p>我很想去研究这个宇宙， 而不是沉浸在虚拟世界， 走错了路，错乱了方向</p><p>深爱着物理学，却屈服于现实</p><h3 id="_04-20" tabindex="-1">04/20 <a class="header-anchor" href="#_04-20" aria-label="Permalink to &quot;04/20&quot;">​</a></h3><p>时间管理721<br> 70%时间用于当天工作，20%用于明天准备，10%用于下周计划筹措；</p><h3 id="_02-25" tabindex="-1">02/25 <a class="header-anchor" href="#_02-25" aria-label="Permalink to &quot;02/25&quot;">​</a></h3><p>价值实现与产出财富 也就是在我现在这个年纪 还有必要去争取一个更高的学位吗</p><h3 id="_02-23" tabindex="-1">02/23 <a class="header-anchor" href="#_02-23" aria-label="Permalink to &quot;02/23&quot;">​</a></h3><p>“今朝笑话讲的好，明晚子弹喂到饱”</p><p>“你成绩好差啊 居然不是全省状元”</p><h2 id="_2018" tabindex="-1">2018 <a class="header-anchor" href="#_2018" aria-label="Permalink to &quot;2018&quot;">​</a></h2><h3 id="_07-22" tabindex="-1">07/22 <a class="header-anchor" href="#_07-22" aria-label="Permalink to &quot;07/22&quot;">​</a></h3><p>就想换个专业<br> 从新来过</p><p>——理论物理、电子物理、生物化学、医学生化、量子生化、物理化学、药物化学、量子力学、天体物理、凝聚态物理</p><p>太晚了</p><h3 id="_06-26" tabindex="-1">06/26 <a class="header-anchor" href="#_06-26" aria-label="Permalink to &quot;06/26&quot;">​</a></h3><p>课程学习<br> 声优代替声音，<br> 爱豆代替表象，</p><h3 id="_06-07" tabindex="-1">06/07 <a class="header-anchor" href="#_06-07" aria-label="Permalink to &quot;06/07&quot;">​</a></h3><p>我有过无数个幻想<br> 咖啡馆的欢笑，西式餐厅的调侃，<br> 你的校园完美的邂逅，<br> 可惜现实中只有我一个，<br> 你依旧在幻想中，</p><h3 id="_03-07" tabindex="-1">03/07 <a class="header-anchor" href="#_03-07" aria-label="Permalink to &quot;03/07&quot;">​</a></h3><p>男生做饭会加分，其实是个伪命题，关键还是看脸，宋仲基就算连米都不会淘你也恨不得加分加到顶，而武大郎还会做烧饼呢？你加吗？</p><h2 id="_2017" tabindex="-1">2017 <a class="header-anchor" href="#_2017" aria-label="Permalink to &quot;2017&quot;">​</a></h2><p>妄念生过错<br> 过错引来贪欲<br> 而贪欲过后<br> 永远跟着后悔<br> 可是后悔无法挽回<br> 所以后悔是残忍的</p><p>说得越多<br> 越容易被抓住破绽<br> 越想掩盖的东西<br> 越容易显露出来</p><p>身体得自己照顾好<br> 你再难受也没人替你照顾</p><p>其实有时候让你一个人长久的活下去也是一种折磨</p>',63)])])}const c=e(o,[["render",l]]);export{_ as __pageData,c as default};
